#if UNITY_EDITOR
using UnityEngine;
using System.Collections;
using System.IO;
using System.Text;
using GuerraDeEmpujes;
public sealed class OnlineIntegrationChecks:MonoBehaviour
{
 StringBuilder report=new StringBuilder();MobileRoundGame game;OnlineSession net;
 void Check(bool ok,string text){report.AppendLine((ok?"PASS ":"FAIL ")+text);File.WriteAllText("Logs/OnlineIntegration.txt",report.ToString());if(!ok)throw new System.Exception(text);}
 IEnumerator Wait(System.Func<bool> condition,float seconds=20){float until=Time.realtimeSinceStartup+seconds;while(!condition()&&Time.realtimeSinceStartup<until)yield return null;Check(condition(),"wait "+condition.Method.Name);}
 IEnumerator Start(){yield return null;game=FindFirstObjectByType<MobileRoundGame>();net=game.Network;yield return Wait(()=>game.FrontEnd&&game.FrontEnd.IsOpen);net.Connect(true,"",2);yield return Wait(()=>net.Code.Length==8);File.WriteAllText("Tools/Multiplayer/probe-room.json",JsonUtility.ToJson(new OnlinePacket{code=net.Code,message=net.Endpoint}));net.SetReady();yield return Wait(()=>net.Peers.Length==2&&net.Peers[0].ready&&net.Peers[1].ready,45);net.StartMatch();yield return Wait(()=>net.Playing);Check(game.Fighters.Count==2,"two real actors");Check(game.Fighters.TrueForAll(p=>!p.GetComponent<MobileArenaBot>()),"no bots in online match");Check(game.SelectedHero==2,"host chosen hero");yield return Wait(()=>game.OnlineProgress[1].spells[0]==2);Check(game.OnlineProgress[1].gold==500,"remote upgrade charged once");game.Ready();yield return Wait(()=>game.Phase==ArenaPhase.Fighting);var start=game.Fighters[1].transform.position;yield return new WaitForSeconds(1.5f);Check(Vector3.Distance(start,game.Fighters[1].transform.position)>.1f,"remote input moves host-authoritative actor");yield return Wait(()=>game.Fighters[1].GetComponent<SpellLoadout>().slots[0].readyAt>Time.time);Check(game.Fighters[1].GetComponent<CharacterAnimationDriver>().IsCasting,"remote cast accepted with animation");game.FrontEnd.ShowHome();float time=game.TimeLeft;yield return new WaitForSecondsRealtime(.4f);Check(Time.timeScale==1&&game.TimeLeft<time,"host menu keeps online simulation running");game.FrontEnd.Close();var remote=game.Fighters[1].GetComponent<ArenaHealth>();remote.invulnerable=false;remote.TakeDamage(1000,game.Player.GetComponent<ArenaHealth>());Check(game.Phase==ArenaPhase.Result,"host determines winner");Check(game.progress.gold==1075,"win and kill rewards authoritative");yield return Wait(()=>game.Phase==ArenaPhase.Shop);Check(game.Round==2&&game.OnlineProgress[1].spells[0]==2,"next round keeps each player's upgrades");Check(game.OnlineProgress[1].gold==750,"loser receives round gold");Check(Mathf.Abs(game.Player.GetComponent<ArenaCharacterMotor>().moveSpeed-2.72f)<.001f,"base speed increased to 2.72");string roomCode=net.Code;for(int n=2;n<=5;n++){game.Ready();yield return Wait(()=>game.Phase==ArenaPhase.Fighting);game.Fighters[1].GetComponent<ArenaHealth>().TakeDamage(1000,game.Player.GetComponent<ArenaHealth>());yield return Wait(()=>game.Phase==ArenaPhase.Shop);Check(net.Playing&&net.Code==roomCode&&!game.MenuOpen,"round "+n+" remains inside same room");}Check(game.Round==6&&game.OnlineProgress[1].spells[0]==2,"sixth round opens shop and preserves upgrades");Check(game.BuySpell(1),"can buy after fifth round");game.NewMatch();Check(net.Playing&&net.Code==roomCode,"new match never disconnects online session");net.Leave();Check(!game.Online&&game.Fighters.Count==4,"leave restores local match");report.AppendLine("COMPLETE");File.WriteAllText("Logs/OnlineIntegration.txt",report.ToString());}
}

#endif
